code.java:
public int hammingWeight(int n) {
    int count = 0;
    for (int i = 0; i < 32; i++) {
        count += (n & 1);
        n >>>= 1;
    }
    return count;
}

code.python:
def hammingWeight(self, n: int) -> int:
    count = 0
    while n:
        count += n & 1
        n >>= 1
    return count

code.java:
public int hammingWeight(int n) {
    int count = 0;
    while (n != 0) {
        n &= (n - 1);
        count++;
    }
    return count;
}

code.python:
def hammingWeight(self, n: int) -> int:
    count = 0
    while n:
        n &= n - 1
        count += 1
    return count

